class Solution {
    int count = 0;
    unordered_map<long long, int> prefixCounts;
    void dfs(TreeNode* node, long long currSum, int targetSum) {
        if (!node) return;
        currSum += node->val;
        auto it = prefixCounts.find(currSum - targetSum);
        if (it != prefixCounts.end()) count += it->second;
        prefixCounts[currSum]++;
        dfs(node->left, currSum, targetSum);
        dfs(node->right, currSum, targetSum);
        prefixCounts[currSum]--;
    }
public:
    int pathSum(TreeNode* root, int targetSum) {
        count = 0;
        prefixCounts.clear();
        prefixCounts[0] = 1;
        dfs(root, 0, targetSum);
        return count;
    }
};

class Solution {
    private int count = 0;
    private Map<Long, Integer> prefixCounts = new HashMap<>();

    private void dfs(TreeNode node, long currSum, int targetSum) {
        if (node == null) return;
        currSum += node.val;
        count += prefixCounts.getOrDefault(currSum - targetSum, 0);
        prefixCounts.put(currSum, prefixCounts.getOrDefault(currSum, 0) + 1);
        dfs(node.left, currSum, targetSum);
        dfs(node.right, currSum, targetSum);
        prefixCounts.put(currSum, prefixCounts.get(currSum) - 1);
    }

    public int pathSum(TreeNode root, int targetSum) {
        count = 0;
        prefixCounts.clear();
        prefixCounts.put(0L, 1);
        dfs(root, 0L, targetSum);
        return count;
    }
}

